'use strict';

/**
 * Берет информацию про пользователя из express-blackbox
 * @returns {Function}
 * @see https://github.yandex-team.ru/project-stub/express-blackbox
 */
module.exports = () => {
    /**
     * @param {Object} record
     * @returns {undefined}
     */
    return record => {
        let req = record.req;
        if (!req || !req.blackbox || !req.blackbox.uid) {
            return;
        }

        record.user = {
            uid: req.blackbox.uid,
        };
    };
};
